from solution import Entry, Report, solve

assert solve([]) == Report(0, 0, 0), 'fixture 0'
assert solve([Entry(11, 15, 3)]) == Report(0, 0, 0), 'fixture 1'
assert solve([Entry(3, 8, 3), Entry(6, 12, 5)]) == Report(0, 0, 0), 'fixture 2'
assert solve([Entry(10, 13, 1), Entry(0, 2, 1), Entry(1, 6, 4)]) == Report(0, 0, 0), 'fixture 3'
assert solve([Entry(3, 6, 3), Entry(5, 10, 2), Entry(7, 8, 2), Entry(6, 13, 3)]) == Report(1, 2, 1), 'fixture 4'
assert solve([Entry(0, 5, 5), Entry(9, 12, 2), Entry(6, 7, 2), Entry(4, 5, 4), Entry(8, 15, 2)]) == Report(1, 2, 3), 'fixture 5'
assert solve([Entry(1, 8, 5), Entry(7, 13, 5), Entry(5, 9, 1), Entry(10, 14, 5), Entry(9, 11, 5), Entry(0, 2, 3)]) == Report(4, 4, 3), 'fixture 6'
assert solve([Entry(1, 5, 2), Entry(0, 1, 4), Entry(6, 12, 4), Entry(11, 12, 5), Entry(7, 14, 2), Entry(5, 12, 1), Entry(0, 3, 2)]) == Report(1, 2, 2), 'fixture 7'
assert solve([Entry(10, 14, 2), Entry(10, 17, 1), Entry(7, 8, 3), Entry(9, 11, 4), Entry(11, 12, 4), Entry(9, 12, 4), Entry(2, 3, 3), Entry(3, 9, 3)]) == Report(3, 5, 2), 'fixture 8'
assert solve([Entry(2, 9, 5), Entry(5, 7, 4), Entry(4, 6, 3), Entry(4, 11, 5), Entry(5, 9, 2), Entry(10, 11, 3), Entry(0, 4, 1), Entry(6, 11, 3), Entry(3, 4, 1)]) == Report(3, 6, 5), 'fixture 9'
assert solve([Entry(7, 8, 1), Entry(2, 7, 1), Entry(1, 7, 2), Entry(11, 14, 4), Entry(9, 12, 1), Entry(5, 8, 5), Entry(8, 11, 3), Entry(2, 4, 1), Entry(4, 6, 3), Entry(8, 11, 5)]) == Report(1, 2, 2), 'fixture 10'
assert solve([Entry(6, 12, 4), Entry(0, 2, 4), Entry(7, 9, 1), Entry(4, 5, 5), Entry(6, 8, 2), Entry(8, 14, 5), Entry(9, 14, 2), Entry(9, 14, 2), Entry(3, 7, 2), Entry(2, 8, 2), Entry(7, 11, 3)]) == Report(4, 5, 5), 'fixture 11'
assert solve([Entry(9, 12, 3), Entry(5, 12, 2), Entry(3, 8, 1), Entry(5, 7, 2), Entry(4, 6, 2), Entry(9, 10, 2), Entry(1, 8, 4), Entry(11, 15, 1), Entry(6, 10, 2), Entry(8, 9, 4), Entry(1, 6, 4), Entry(6, 12, 3)]) == Report(9, 9, 5), 'fixture 12'
assert solve([Entry(1, 3, 4)]) == Report(0, 0, 0), 'fixture 13'
assert solve([Entry(0, 4, 4), Entry(2, 5, 1)]) == Report(0, 0, 0), 'fixture 14'
assert solve([Entry(8, 10, 4), Entry(7, 10, 1), Entry(7, 9, 2)]) == Report(0, 0, 0), 'fixture 15'
assert solve([Entry(4, 9, 3), Entry(8, 12, 5), Entry(0, 3, 3), Entry(8, 15, 5)]) == Report(1, 2, 4), 'fixture 16'
assert solve([Entry(10, 12, 1), Entry(10, 11, 4), Entry(6, 9, 3), Entry(10, 14, 1), Entry(8, 9, 1)]) == Report(1, 2, 2), 'fixture 17'
assert solve([Entry(5, 9, 1), Entry(3, 7, 3), Entry(4, 10, 1), Entry(9, 16, 5), Entry(10, 12, 5), Entry(9, 16, 1)]) == Report(3, 5, 4), 'fixture 18'
assert solve([Entry(3, 8, 2), Entry(3, 5, 3), Entry(0, 6, 5), Entry(2, 9, 4), Entry(8, 13, 1), Entry(8, 10, 1), Entry(10, 11, 1)]) == Report(2, 3, 2), 'fixture 19'
assert solve([Entry(7, 14, 3), Entry(8, 15, 1), Entry(2, 9, 2), Entry(10, 11, 3), Entry(3, 5, 1), Entry(5, 7, 2), Entry(10, 12, 3), Entry(4, 9, 4)]) == Report(4, 5, 2), 'fixture 20'
assert solve([Entry(0, 2, 1), Entry(2, 4, 1)]) == Report(0, 0, 0), 'fixture 21'
assert solve([Entry(0, 3, 1), Entry(0, 3, 1), Entry(0, 3, 2)]) == Report(1, 2, 3), 'fixture 22'
assert solve([Entry(0, 4, 1), Entry(4, 9, 1), Entry(2, 6, 1), Entry(0, 8, 2)]) == Report(2, 3, 2), 'fixture 23'
